import (
	context "context"
	fernclient "github.com/go-optional-header-env/fern/client"
	option "github.com/go-optional-header-env/fern/option"
)

client := fernclient.NewClient(
	option.WithAPIKey(
		"<YOUR_AUTH_TOKEN>",
	),
)
response, err := client.Service.GetWithAPIVersion(
	context.TODO(),
)
